func TestMCPFramingRecoversFromMalformedAndOversizedMessages(t *testing.T) {
	ping := `{"jsonrpc":"2.0","id":1,"method":"ping"}` + "\n"
	oversized := `{"x":"` + strings.Repeat("x", contract.MaxMCPMessageBytes) + `"}` + "\n"
	input := strings.NewReader("{not-json}\n" + oversized + ping)
	var output bytes.Buffer
	if err := runMCP(input, &output); err != nil {
		t.Fatal(err)
	}
	lines := strings.Split(strings.TrimSpace(output.String()), "\n")
	if len(lines) != 3 || !strings.Contains(lines[0], `"code":-32700`) ||
		!strings.Contains(lines[1], `"code":-32600`) ||
		!strings.Contains(lines[2], `"id":1`) {
		t.Fatalf("framing did not recover after bad messages: %q", output.String())
	}
}

func TestMCPAnswersEveryRequestAndNoNotification(t *testing.T) {
	cases := []struct {
		name  string
		input string
		want  []string // substrings, one per expected output line; nil = no output
	}{
		{"initialized notification", `{"jsonrpc":"2.0","method":"notifications/initialized"}`, nil},
		{"cancelled notification", `{"jsonrpc":"2.0","method":"notifications/cancelled","params":{"requestId":3}}`, nil},
		{"request without id is not executed", `{"jsonrpc":"2.0","method":"tools/list"}`, nil},
		{"client response", `{"jsonrpc":"2.0","id":7,"result":{}}`, nil},
		{"non-object message", `5`, []string{`"code":-32600`}},
		{"wrong jsonrpc version", `{"jsonrpc":2,"id":3,"method":"ping"}`, []string{`"id":3`, `"code":-32600`}},
		{"null id", `{"jsonrpc":"2.0","id":null,"method":"ping"}`, []string{`"id":null`, `"code":-32600`}},
		{"method not a string", `{"jsonrpc":"2.0","id":4,"method":5}`, []string{`"code":-32600`}},
		{"params not an object", `{"jsonrpc":"2.0","id":5,"method":"tools/list","params":[]}`, []string{`"code":-32602`}},
		{"arguments not an object", `{"jsonrpc":"2.0","id":6,"method":"tools/call","params":{"name":"GUI","arguments":[]}}`, []string{`"code":-32602`}},
		{"missing tool name", `{"jsonrpc":"2.0","id":8,"method":"tools/call","params":{}}`, []string{`"code":-32602`}},
		{"empty batch", `[]`, []string{`"code":-32600`}},
		{"batch", `[{"jsonrpc":"2.0","id":"a","method":"ping"},{"jsonrpc":"2.0","method":"notifications/initialized"}]`, []string{`"id":"a"`}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var output bytes.Buffer
			if err := runMCP(strings.NewReader(tc.input+"\n"), &output); err != nil {
				t.Fatal(err)
			}
			got := strings.TrimSpace(output.String())
			if tc.want == nil {
				if got != "" {
					t.Fatalf("expected no response, got %q", got)
				}
				return
			}
			for _, want := range tc.want {
				if !strings.Contains(got, want) {
					t.Fatalf("response %q does not contain %q", got, want)
				}
			}
		})
	}
}

func TestMCPRequestDecodePreservesExactJSONNumbers(t *testing.T) {
	request, err := decodeMCPRequest([]byte(
		`{"jsonrpc":"2.0","id":1,"method":"tools/call","params":` +
			`{"name":"AX","arguments":{"mode":"observe","until":` +
			`{"type":"value","ref":"r1",` +
			`"value":9007199254740993}}}}`,
	))
	if err != nil {
		t.Fatal(err)
	}
	params := request["params"].(map[string]any)
	arguments := params["arguments"].(map[string]any)
	assertion := arguments["until"].(map[string]any)
	value, ok := assertion["value"].(json.Number)
	if !ok || value.String() != "9007199254740993" {
		t.Fatalf("MCP transport changed exact JSON number: %#v",
			assertion["value"])
	}
	if _, err := decodeMCPRequest([]byte(`{} {}`)); err == nil {
		t.Fatal("MCP transport accepted multiple JSON values")
	}
}

package contract

import (
	"strings"
)

// Tool-specific wording for argument errors. The schema decides what is
// accepted; these rules only replace a generic explanation with the one
// the model can act on directly.

func init() {
	argumentRules[PublicToolGUI] = toolArgumentRules{
		before: guiShapeProblem,
		refine: refineGUIArgumentError,
	}
}

// guiShapeProblem keeps the GUI observation rules readable: the schema
// splits a screenshot observation and an input batch into two branches,
// and the generic "exactly 1 item" message would hide why.
func guiShapeProblem(args map[string]any) *explanation {
	actions, ok := args["actions"].([]any)
	if !ok {
		if _, present := args["actions"]; !present {
			return &explanation{
				keyword: "required",
				message: `GUI requires actions; use {"actions":[{"type":"screenshot"}]} for an immediate observation`,
			}
		}
		return nil
	}
	if len(actions) == 0 {
		return &explanation{
			path:    []string{"actions"},
			keyword: "minItems",
			message: "GUI actions must not be empty; use one screenshot action for observation",
		}
	}
	observation := ""
	for _, item := range actions {
		if action, ok := item.(map[string]any); ok &&
			(action["type"] == "screenshot" || action["type"] == "zoom") {
			observation, _ = action["type"].(string)
		}
	}
	if observation == "" {
		return nil
	}
	if len(actions) > 1 {
		message := "GUI screenshot must be the only action because no intermediate screenshot is returned"
		if observation == "zoom" {
			message = "GUI zoom must be the only action: it reads the current frame and sends no input"
		}
		return &explanation{
			path:    []string{"actions"},
			keyword: "oneOf",
			message: message,
		}
	}
	if _, present := args["settle_ms"]; present {
		return &explanation{
			path:    []string{"settle_ms"},
			keyword: "additionalProperties",
			message: "GUI " + observation + " observation does not accept settle_ms",
		}
	}
	return nil
}

func refineGUIArgumentError(args map[string]any, found *explanation) {
	if found.keyword == "additionalProperties" && len(found.path) == 0 {
		found.message = strings.Replace(found.message, "GUI does not accept fields:",
			"GUI accepts only actions and optional settle_ms; unsupported field(s):", 1)
		found.accepted = ""
	}
}

// Cross-field rules that no schema keyword expresses. The runtime enforces
// them after the schema gate, before any input, and marks the rejection with
// its rule code so the consistency test can tell a declared rule from drift.
const (
	ArgumentRuleCloseNotLast    = "close_not_last"
	ArgumentRuleTextBudget      = "text_budget"
	ArgumentRuleRefOwnsIdentity = "ref_owns_identity"
	ArgumentRuleWaitBudget      = "wait_budget"
	// ArgumentRuleOneInputStep is the batching ablation's limit of one
	// input step per act.
	ArgumentRuleOneInputStep = "one_input_step"
)

// ArgumentRuleError is a cross-field rule violation.
type ArgumentRuleError struct {
	Code    string `json:"-"`
	message string
}

func (e *ArgumentRuleError) Error() string { return e.message }

func NewArgumentRuleError(code, message string) error {
	return &ArgumentRuleError{Code: code, message: message}
}

