from __future__ import annotations

import logging
import time
from typing import Any

import requests


class CDPConnectionError(RuntimeError):
    """Raised after bounded attempts to connect to an existing CDP endpoint."""


def _endpoint_diagnostic(url: str) -> str:
    endpoint = url.rstrip("/") + "/json/version"
    try:
        response = requests.get(endpoint, timeout=3)
        body = response.text[:300].replace("\n", " ")
        return f"GET {endpoint} -> {response.status_code}: {body!r}"
    except Exception as exc:
        return f"GET {endpoint} -> {type(exc).__name__}: {exc}"


def connect_over_cdp_with_retry(
    chromium: Any,
    url: str,
    *,
    attempts: int = 3,
    initial_delay: float = 1.0,
    logger: logging.Logger | None = None,
) -> Any:
    if attempts < 1:
        raise ValueError("attempts must be positive")
    log = logger or logging.getLogger("desktopenv.cdp")
    failures: list[str] = []

    for attempt in range(1, attempts + 1):
        try:
            return chromium.connect_over_cdp(url)
        except Exception as exc:
            diagnostic = _endpoint_diagnostic(url)
            failure = (
                f"attempt {attempt}/{attempts}: "
                f"{type(exc).__name__}: {exc}; {diagnostic}"
            )
            failures.append(failure)
            log.warning("CDP connection failed: %s", failure)
            if attempt < attempts:
                time.sleep(initial_delay * (2 ** (attempt - 1)))

    raise CDPConnectionError(
        f"CDP connection failed after {attempts} attempts at {url}: "
        + " | ".join(failures)
    )

#!/usr/bin/env python3
"""Keep APT and PackageKit binary package caches local to each process."""

import os
from pathlib import Path


CONFIG = '''// APT and PackageKit can otherwise delete each other's temporary binary caches.
// Keep package indexes and archive downloads; build binary caches in memory.
Dir::Cache::pkgcache "";
Dir::Cache::srcpkgcache "";
'''
CONFIG_PATH = Path("/etc/apt/apt.conf.d/99hcu-apt-cache")


def configure(path=CONFIG_PATH):
    if path.is_symlink() or (path.exists() and (
            not path.is_file() or path.read_text() != CONFIG)):
        raise RuntimeError("APT cache configuration path is already occupied: " + str(path))
    path.write_text(CONFIG)
    path.chmod(0o644)


if __name__ == "__main__":
    if os.geteuid() != 0:
        raise RuntimeError("Run APT configuration as root inside the guest")
    configure()
    print("APT binary disk caches disabled; boot the exported image to apply this to all package readers.")

"""Set desktop preferences without creating documents or task state."""
from pathlib import Path
import configparser
import argparse
import json
import os


SETTINGS = {
    ".config/Kingsoft/Office.conf": {
        "6.0": {
            "common\\do_not_detect_file_association_while_startup": "true",
        },
    },
    ".config/MuseScore/MuseScore4.ini": {
        "application": {
            "welcomeDialogShowOnStartup": "false",
        },
    },
    ".config/slicer.org/Slicer.ini": {
        "MainWindow": {"DontShowDisclaimerMessage": "1024"},
        "ApplicationUpdate": {"AutoUpdateCheck": "false"},
    },
}


def configure(home, manifest):
    settings = {**SETTINGS,
        ".config/REAPER/reaper.ini": {
            "reaper": {"linux_audio_mode": "3", "verchk": "0"}},
    }
    for relative, sections in settings.items():
        path = home / relative
        parser = configparser.ConfigParser(interpolation=None, strict=False)
        parser.optionxform = str
        if path.exists():
            parser.read(path)
        for section, values in sections.items():
            if not parser.has_section(section):
                parser.add_section(section)
            for key, value in values.items():
                parser.set(section, key, value)
        if relative.endswith("MuseScore4.ini"):
            parser.set("application", "skippedVersion", manifest["musescore_skipped_version"])
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("w") as stream:
            parser.write(stream, space_around_delimiters=False)
        print(path)


if __name__ == "__main__":
    if os.getuid() == 0:
        raise SystemExit("Run as the guest desktop user")
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--home", type=Path, default=Path.home())
    parser.add_argument("--manifest", type=Path, required=True)
    args = parser.parse_args()
    configure(args.home, json.loads(args.manifest.read_text()))

"""Disable Thunderbird's unsolicited startup pages without changing mail profiles."""

import argparse
import json
from pathlib import Path


PREFERENCES = '''// Computer Use desktop image: suppress unsolicited startup pages.
// The donation check compares the viewed campaign with this campaign number.
pref("app.donation.eoy.version", 0);
// Disabling data submission also prevents its first-run privacy page.
pref("datareporting.policy.dataSubmissionEnabled", false);
// Leave the message pane empty until a message is selected.
pref("mailnews.start_page.enabled", false);
'''


def configure(application):
    directory = application / "defaults/pref"
    if not (application / "omni.ja").is_file() or not directory.is_dir():
        raise ValueError("Expected an unpacked Thunderbird application with defaults/pref")
    path = directory / "hcu-startup.js"
    if path.is_symlink():
        raise ValueError("Refusing to follow a startup preferences symlink: " + str(path))
    if path.exists() and path.read_text() != PREFERENCES:
        raise ValueError("Refusing to overwrite different startup preferences: " + str(path))
    path.write_text(PREFERENCES)
    path.chmod(0o644)
    return {"preferences": str(path), "mail_profiles_changed": False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--application", type=Path, default=Path("/usr/lib/thunderbird"))
    args = parser.parse_args()
    print(json.dumps(configure(args.application)))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Enable the bundled Qt accessibility bridge at each WPS launcher."""

import os
from pathlib import Path


VARIABLE = b"QT_LINUX_ACCESSIBILITY_ALWAYS_ON"
EXPORT = b"export " + VARIABLE + b"=1\n"
APPLICATIONS = ("wps", "wpp", "et")


def configure(bin_directory=Path("/usr/bin")):
    updates = []
    # Validate every entry before changing any launcher in the suite.
    for name in APPLICATIONS:
        path = bin_directory / name
        if path.is_symlink() or not path.is_file():
            raise RuntimeError("Expected a regular WPS launcher: " + str(path))
        original = path.read_bytes()
        shebang, separator, body = original.partition(b"\n")
        if shebang != b"#!/bin/bash" or not separator or not os.access(path, os.X_OK):
            raise RuntimeError("Unrecognized WPS launcher: " + str(path))
        if body.startswith(EXPORT) and VARIABLE not in body[len(EXPORT):]:
            continue
        if VARIABLE in body:
            raise RuntimeError("Conflicting Qt accessibility setting: " + str(path))
        if not body.startswith(b"\n"):
            raise RuntimeError("Expected a blank line after the WPS shebang: " + str(path))
        # Replace that blank line to preserve line numbers in shell diagnostics.
        updates.append((path, shebang + separator + EXPORT + body[1:]))
    for path, contents in updates:
        # Keep the vendor's argument parsing, process routing and exit behavior.
        path.write_bytes(contents)
    return {"launchers": [str(bin_directory / name) for name in APPLICATIONS],
            "updated": len(updates)}


if __name__ == "__main__":
    if os.geteuid() != 0:
        raise RuntimeError("Run WPS accessibility configuration as root inside the guest")
    print(configure())
